DROP TABLE IF EXISTS iceberg.bronze.account_changed;

CREATE TABLE iceberg.bronze.account_changed
WITH (format = 'PARQUET') AS
SELECT DISTINCT s.recid
FROM iceberg.bronze.account_stage AS s
CROSS JOIN (
  SELECT COALESCE(
    date_add('day', -1, max(source_updated_date)),
    DATE '1900-01-01'
  ) AS lower_bound
  FROM iceberg.bronze.account
) AS w
WHERE s.source_updated_date >= w.lower_bound
   OR s.source_updated_date IS NULL;

MERGE INTO iceberg.bronze.account AS t
USING (
  SELECT s.*
  FROM iceberg.bronze.account_stage AS s
  JOIN iceberg.bronze.account_changed AS c ON c.recid = s.recid
) AS s
ON t.recid = s.recid
WHEN MATCHED AND t.xml_hash IS DISTINCT FROM s.xml_hash THEN UPDATE SET
  account_number = s.account_number,
  customer = s.customer,
  category = s.category,
  account_title_1 = s.account_title_1,
  account_title_2 = s.account_title_2,
  short_title = s.short_title,
  mnemonic = s.mnemonic,
  position_type = s.position_type,
  currency = s.currency,
  currency_market = s.currency_market,
  limit_ref = s.limit_ref,
  account_officer = s.account_officer,
  other_officer = s.other_officer,
  posting_restrict = s.posting_restrict,
  reconcile_acct = s.reconcile_acct,
  interest_liqu_acct = s.interest_liqu_acct,
  interest_comp_acct = s.interest_comp_acct,
  int_no_booking = s.int_no_booking,
  referal_code = s.referal_code,
  waive_ledger_fee = s.waive_ledger_fee,
